(function(){document.addEventListener('DOMContentLoaded',()=>{const form=document.querySelector('[data-consultation-form]');if(!form)return;let step=1;const max=5;const show=n=>{step=Math.max(1,Math.min(max,n));form.querySelectorAll('[data-step]').forEach(panel=>panel.hidden=Number(panel.dataset.step)!==step);form.querySelectorAll('[data-step-dot]').forEach(dot=>{dot.classList.toggle('is-active',Number(dot.dataset.stepDot)<=step);dot.setAttribute('aria-current',Number(dot.dataset.stepDot)===step?'step':'false');});form.querySelector('[data-step-label]').textContent=`Step ${step} of ${max}`;form.querySelector('[data-prev]').hidden=step===1;form.querySelector('[data-next]').hidden=step===max;form.querySelector('[data-submit-consult]').hidden=step!==max;};form.addEventListener('click',e=>{if(e.target.closest('[data-next]')){const panel=form.querySelector(`[data-step="${step}"]`);const required=[...panel.querySelectorAll('[required]')];if(required.every(x=>x.reportValidity()))show(step+1);}if(e.target.closest('[data-prev]'))show(step-1);});form.addEventListener('submit',e=>{e.preventDefault();form.innerHTML=`<div class="request-complete"><span>✓</span><p class="eyebrow">Request prepared</p><h2>Thank you — your consultation request is ready.</h2><p>This frontend does not transmit personal information. Connect a secure form service before using this flow in practice.</p><a class="button" href="products.html">Browse the store</a></div>`;});show(1);});})();
